-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_ASTRAZENECA_TEASER.SNOWBOTS.T_CLOSE_SENTINEL
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/London'
  CONFIG = '{"autonomy": 3}'
  WHEN SYSTEM$STREAM_HAS_DATA('SDP_ASTRAZENECA_TEASER.PUBLIC.STR_GL_JOURNAL')
AS
  CALL SDP_ASTRAZENECA_TEASER.SNOWBOTS.SP_RUN_BOT('close-sentinel');

-- step 1 · Actuals landed: Q3 GL across 8 feeds
SELECT SYSTEM$STREAM_HAS_DATA('SDP_ASTRAZENECA_TEASER.PUBLIC.STR_GL_JOURNAL') OR SYSTEM$STREAM_HAS_DATA('SDP_ASTRAZENECA_TEASER.PUBLIC.STR_ALX_JOURNAL');
-- step 2 · Completeness DMFs per feed
SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_ASTRAZENECA_TEASER.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-09';
-- step 3 · Fallback: paged re-extract of the Alexion ledger
CALL SDP_ASTRAZENECA_TEASER.SNOWBOTS.SP_REEXTRACT('ALEXION_ERP', '2026-09', page_size => 100000);
-- step 4 · Reconcile balance sheet + intercompany pairs
CALL SDP_ASTRAZENECA_TEASER.SNOWBOTS.SP_RECONCILE(period => '2026-09', tolerance_pct => 0.5);
-- step 5 · Guardrail: completeness ≥ 99% and TB difference = 0
SELECT MIN(completeness) >= 0.99 AND ABS(SUM(tb_diff)) = 0 FROM SDP_ASTRAZENECA_TEASER.SNOWBOTS.V_CLOSE_STATUS WHERE period = '2026-09';
-- step 6 · Lock period 2026-09 (awaiting Group Controller approval)
CALL SDP_ASTRAZENECA_TEASER.PUBLIC.SP_LOCK_PERIOD('2026-09', approved_by => :approver);

