-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_ASTRAZENECA_TEASER.SNOWBOTS.T_DRIVER_REFRESH
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/London'
  CONFIG = '{"autonomy": 4}'
AS
  CALL SDP_ASTRAZENECA_TEASER.SNOWBOTS.SP_RUN_BOT('driver-refresh');

-- step 1 · Marketplace share refreshed
SELECT MAX(date) FROM FX_MARKETPLACE.PUBLIC.FX_RATES_DAILY;
-- step 2 · Upsert group closing and average rates
MERGE INTO SDP_ASTRAZENECA_TEASER.PUBLIC.FACT_FX_RATE t USING (SELECT * FROM FX_MARKETPLACE.PUBLIC.FX_RATES_DAILY WHERE date = CURRENT_DATE) s ON t.pair = s.pair ...;
-- step 3 · Guardrail: daily move ≤ 3%
SELECT MAX(ABS(pct_change)) <= 0.03 FROM SDP_ASTRAZENECA_TEASER.SNOWBOTS.V_FX_MOVES;
-- step 4 · Recalculate Q4 forecast at current rates
CALL SDP_ASTRAZENECA_TEASER.PUBLIC.SP_RECALC(scope => 'FX', from_period => '2026-10');

