SELECT c.vendor, c.unit_price / b.p50 - 1 AS premium FROM ... JOIN SDP_ASTRAZENECA_TEASER.SNOWBOTS.V_VENDOR_BENCHMARK b ...;
-- step 3 · Recommendations to Procurement
INSERT INTO SDP_ASTRAZENECA_TEASER.PUBLIC.NOTIFICATIONS ...;

